1	import type { RequestContext } from "@mastra/core/request-context";
2	import { createTool } from "@mastra/core/tools";
3	import { MCPClient, type RequireToolApprovalContext } from "@mastra/mcp";
4	import { isTraceOwner, recordTraceOwners } from "../../neatlogs/trace-owners";
5	import { USER_ROLE_KEY, WORKSPACE_USER_KEY } from "../workspace";
6	
7	/**
8	 * Neatlogs' MCP tools carry no annotations (no readOnlyHint), so approval is decided by name:
9	 * only these known read tools skip approval. Every other tool (triage/detection writes, and any
10	 * tool the server adds later) needs human approval. Deny by default.
11	 */
12	export const NEATLOGS_READ_TOOLS: ReadonlySet<string> = new Set([
13	  "ping",
14	  "whoami",
15	  "search_traces",
16	  "get_trace_context",
17	  "get_trace_evaluations",
18	  "get_project_analytics",
19	  "list_detections",
20	  "get_detection_trend",
21	  "list_detection_groups",
22	  "get_detection_capabilities",
23	  "get_detection_status",
24	  "triage_list",
25	  "triage_get",
26	  "triage_get_investigation",
27	  "triage_list_steps",
28	  "triage_list_versions",
29	  "triage_get_version",
30	]);
31	
32	/** Never exposed to the agent: it ingests traces rather than reading or triaging them. */
33	const NEATLOGS_EXCLUDED_TOOLS: ReadonlySet<string> = new Set(["log_trace"]);
34	
35	export function neatlogsToolNeedsApproval({ toolName }: Pick<RequireToolApprovalContext, "toolName">): boolean {
36	  return !NEATLOGS_READ_TOOLS.has(toolName);
37	}
38	
39	// Neatlogs' hosted MCP server, authenticated with the same project key the tracing SDK uses.
40	export const neatlogsMcp = new MCPClient({
41	  id: "neatlogs",
42	  servers: {
43	    neatlogs: {
44	      url: new URL("https://ingest.neatlogs.com/mcp"),
45	      requestInit: {
46	        headers: { Authorization: `Bearer ${process.env.NEATLOGS_API_KEY}` },
47	      },
48	      // Refuse to follow redirects/requests to any other host with the key attached.
49	      allowedHosts: ["ingest.neatlogs.com"],
50	      requireToolApproval: neatlogsToolNeedsApproval,
51	    },
52	  },
53	});
54	
55	type NeatlogsTools = Awaited<ReturnType<typeof neatlogsMcp.listTools>>;
56	let cached: NeatlogsTools | undefined;
57	
58	const TOOL_KEY_PREFIX = "neatlogs_"; // listTools() namespaces tools as `<server>_<tool>`.
59	
60	function toolName(key: string): string | undefined {
61	  return key.startsWith(TOOL_KEY_PREFIX) ? key.slice(TOOL_KEY_PREFIX.length) : undefined;
62	}
63	
64	/**
65	 * Resolves the shared Neatlogs MCP tools lazily, minus excluded ones. Degrades to no tools
66	 * (logging a warning) when NEATLOGS_API_KEY is missing or the connection fails, so the server
67	 * still boots. Only a successful, non-empty fetch is cached. Never mutate the cached tools: they
68	 * are shared by every request; per-user scoping builds new wrapper tools instead.
69	 */
70	async function getAllNeatlogsTools(): Promise<NeatlogsTools> {
71	  if (cached) return cached;
72	  if (!process.env.NEATLOGS_API_KEY) {
73	    console.warn("[neatlogs] NEATLOGS_API_KEY is not set; the Neatlogs agent has no tools");
74	    return {};
75	  }
76	  try {
77	    // listTools() reports a failed server as an empty result instead of throwing; don't cache that.
78	    const all = await neatlogsMcp.listTools();
79	    const tools = Object.fromEntries(
80	      Object.entries(all).filter(([key]) => {
81	        const name = toolName(key);
82	        return name !== undefined && !NEATLOGS_EXCLUDED_TOOLS.has(name);
83	      }),
84	    ) as NeatlogsTools;
85	    if (Object.keys(tools).length > 0) cached = tools;
86	    return tools;
87	  } catch (error) {
88	    console.warn("[neatlogs] could not load Neatlogs MCP tools:", error instanceof Error ? error.message : error);
89	    return {};
90	  }
91	}
92	
93	/**
94	 * Whose traces the Neat Bot may show in this request:
95	 * - "all": admins, and runs with no user in the RequestContext at all. Only the CLI (`npm start`)
96	 *   and `mastra dev` run without one; every web request (src/chat-api.ts) sets the user and role
97	 *   server-side, so a browser can never reach this branch by omitting them.
98	 * - "own": any other signed-in user (role "employee", or a missing/unknown role: fail closed).
99	 * - "none": a user id that is not a plain string id; no tools at all.
100	 */
101	export type NeatlogsScope = { kind: "all" } | { kind: "own"; userId: string } | { kind: "none" };
102	
103	export function neatlogsScope(requestContext: RequestContext | undefined): NeatlogsScope {
104	  const get = (key: string): unknown => (typeof requestContext?.get === "function" ? requestContext.get(key) : undefined);
105	  const userId = get(WORKSPACE_USER_KEY);
106	  if (userId === undefined || userId === null) return { kind: "all" };
107	  // Session ids are "<userId>:<agentId>", so an id containing ":" could match another user's prefix.
108	  if (typeof userId !== "string" || !userId || userId.includes(":")) return { kind: "none" };
109	  return get(USER_ROLE_KEY) === "admin" ? { kind: "all" } : { kind: "own", userId };
110	}
111	
112	/**
113	 * The Neat Bot's tools for this request. Admins (and the CLI) get every Neatlogs tool unchanged;
114	 * other users get only ping, whoami, search_traces, get_trace_context and get_trace_evaluations,
115	 * wrapped so they see their own traces only (see scopedTools).
116	 */
117	export async function getNeatlogsTools({ requestContext }: { requestContext?: RequestContext } = {}): Promise<NeatlogsTools> {
118	  const scope = neatlogsScope(requestContext);
119	  if (scope.kind === "none") return {};
120	  const all = await getAllNeatlogsTools();
121	  return scope.kind === "all" ? all : scopedTools(all, scope.userId);
122	}
123	
124	type AnyTool = NeatlogsTools[string];
125	type ExecuteContext = Parameters<NonNullable<AnyTool["execute"]>>[1];
126	
127	/** Neatlogs returns at most 100 traces per search page; a non-admin search scans at most this many pages. */
128	const SEARCH_PAGE_SIZE = 100;
129	const SEARCH_MAX_PAGES = 5;
130	const DEFAULT_SEARCH_LIMIT = 20;
131	
132	const NOT_AVAILABLE = "No trace with that id is available to you. Use search_traces to find your own traces.";
133	
134	function refusal(message: string): { error: true; message: string } {
135	  return { error: true, message };
136	}
137	
138	function isRecord(value: unknown): value is Record<string, unknown> {
139	  return value !== null && typeof value === "object" && !Array.isArray(value);
140	}
141	
142	/** Mastra reports invalid tool input as { error: true, message } instead of throwing. */
143	function isToolError(value: unknown): boolean {
144	  return isRecord(value) && value.error === true;
145	}
146	
147	/**
148	 * The JSON payload of a Neatlogs tool result: the single text block of an MCP CallToolResult, or
149	 * the structured value itself. Undefined whenever it cannot be read with certainty (callers then
150	 * return nothing).
151	 */
152	function parseResult(result: unknown): unknown {
153	  if (!isRecord(result)) return undefined;
154	  if (Array.isArray(result.content)) {
155	    if (result.isError === true) return undefined;
156	    const texts = result.content.filter((part) => isRecord(part) && part.type === "text");
157	    if (texts.length !== 1 || typeof texts[0].text !== "string") return undefined;
158	    try {
159	      return JSON.parse(texts[0].text);
160	    } catch {
161	      return undefined;
162	    }
163	  }
164	  return isToolError(result) ? undefined : result;
165	}
166	
167	function intArg(value: unknown, fallback: number, max: number): number {
168	  return typeof value === "number" && Number.isInteger(value) && value >= 0 ? Math.min(value, max) : fallback;
169	}
170	
171	/** Calls the shared tool's execute without touching the tool itself. */
172	async function callThrough(tool: AnyTool, input: Record<string, unknown>, context: ExecuteContext): Promise<unknown> {
173	  if (!tool.execute) throw new Error(`Neatlogs tool ${tool.id} cannot be executed`);
174	  return tool.execute(input as never, context);
175	}
176	
177	/** search_traces limited to the user's own sessions, without project-wide totals. */
178	function ownSearchTraces(original: AnyTool, userId: string): AnyTool {
179	  const sessionPrefix = `${userId}:`;
180	  return createTool({
181	    id: original.id,
182	    description:
183	      "Searches the traces of the current user's own conversations (only traces whose session belongs to this user; other users' runs and CLI runs are never returned). Takes the same filters as the project-wide search. Returns { mode, count, results, more_may_exist }; there is no project-wide total.",
184	    inputSchema: original.inputSchema,
185	    execute: async (input: Record<string, unknown>, context: ExecuteContext) => {
186	      // limit/offset count the user's own results; the server is paged separately. `fields` is
187	      // dropped because filtering needs session_id on every result.
188	      const { limit: rawLimit, offset: rawOffset, fields: _fields, ...filters } = input;
189	      const limit = Math.max(1, intArg(rawLimit, DEFAULT_SEARCH_LIMIT, SEARCH_PAGE_SIZE));
190	      const offset = intArg(rawOffset, 0, SEARCH_PAGE_SIZE * SEARCH_MAX_PAGES);
191	      const wanted = offset + limit;
192	
193	      const own = new Map<string, Record<string, unknown>>();
194	      let mode: unknown;
195	      let exhausted = false;
196	      for (let page = 0; page < SEARCH_MAX_PAGES && own.size < wanted; page++) {
197	        const raw = await callThrough(original, { ...filters, limit: SEARCH_PAGE_SIZE, offset: page * SEARCH_PAGE_SIZE }, context);
198	        if (page === 0 && isToolError(raw)) return raw; // invalid input: nothing was searched
199	        const parsed = parseResult(raw);
200	        const results = isRecord(parsed) && Array.isArray(parsed.results) ? parsed.results : undefined;
201	        if (!results) {
202	          if (page === 0) return { mode: undefined, count: 0, results: [], more_may_exist: false, note: "Could not read the Neatlogs search results." };
203	          break; // keep what earlier pages returned
204	        }
205	        if (page === 0 && isRecord(parsed)) mode = parsed.mode;
206	        for (const result of results) {
207	          if (
208	            isRecord(result) &&
209	            typeof result.trace_id === "string" &&
210	            typeof result.session_id === "string" &&
211	            result.session_id.startsWith(sessionPrefix) &&
212	            !own.has(result.trace_id)
213	          ) {
214	            own.set(result.trace_id, result);
215	          }
216	        }
217	        if (results.length < SEARCH_PAGE_SIZE) {
218	          exhausted = true;
219	          break;
220	        }
221	      }
222	
223	      try {
224	        recordTraceOwners(userId, own.keys());
225	      } catch (error) {
226	        console.warn("[neatlogs] could not record trace owners:", error instanceof Error ? error.message : error);
227	      }
228	      const results = [...own.values()].slice(offset, wanted);
229	      return {
230	        mode: typeof mode === "string" ? mode : undefined,
231	        count: results.length,
232	        results,
233	        more_may_exist: own.size > wanted || !exhausted,
234	      };
235	    },
236	  }) as unknown as AnyTool;
237	}
238	
239	/** A trace_id tool (get_trace_context, get_trace_evaluations) limited to traces the user owns. */
240	function ownTraceTool(original: AnyTool, userId: string, rejectedArgs: readonly string[], description: string): AnyTool {
241	  return createTool({
242	    id: original.id,
243	    description,
244	    inputSchema: original.inputSchema,
245	    execute: async (input: Record<string, unknown>, context: ExecuteContext) => {
246	      const rejected = rejectedArgs.filter((name) => input[name] !== undefined);
247	      if (rejected.length > 0) {
248	        return refusal(`${rejected.join(", ")} ${rejected.length === 1 ? "is" : "are"} not available. Pass the trace_id of one of your own traces (find it with search_traces).`);
249	      }
250	      const traceId = typeof input.trace_id === "string" ? input.trace_id.trim() : "";
251	      if (!traceId) return refusal("trace_id is required. Find your traces with search_traces.");
252	      if (!isTraceOwner(traceId, userId)) return refusal(NOT_AVAILABLE);
253	      const raw = await callThrough(original, { ...input, trace_id: traceId }, context);
254	      if (isToolError(raw)) return raw;
255	      // Fail closed unless the result is readable and about the requested trace.
256	      const parsed = parseResult(raw);
257	      if (!isRecord(parsed) || typeof parsed.trace_id !== "string" || parsed.trace_id.toLowerCase() !== traceId.toLowerCase()) {
258	        return refusal("Could not read the Neatlogs result for that trace.");
259	      }
260	      return raw;
261	    },
262	  }) as unknown as AnyTool;
263	}
264	
265	/**
266	 * Per-request copies for a non-admin: only ping, whoami and the three trace tools, the latter wrapped
267	 * to the user's own traces. ping and whoami return no trace data and are passed through as is.
268	 * Analytics, detections, triage and every write tool are left out.
269	 */
270	function scopedTools(all: NeatlogsTools, userId: string): NeatlogsTools {
271	  const tools: NeatlogsTools = {};
272	  const pick = (name: string) => all[`${TOOL_KEY_PREFIX}${name}`];
273	  for (const name of ["ping", "whoami"]) {
274	    const tool = pick(name);
275	    if (tool) tools[`${TOOL_KEY_PREFIX}${name}`] = tool;
276	  }
277	  const search = pick("search_traces");
278	  if (search) tools[`${TOOL_KEY_PREFIX}search_traces`] = ownSearchTraces(search, userId);
279	  const context = pick("get_trace_context");
280	  if (context) {
281	    tools[`${TOOL_KEY_PREFIX}get_trace_context`] = ownTraceTool(
282	      context,
283	      userId,
284	      ["created_after", "verification_marker", "candidate_offset"],
285	      "Fetches the full context (spans, timings, tokens, errors, first page of evaluations) of one of the current user's own traces by trace_id. Only trace ids from this user's conversations are allowed; created_after and verification_marker are not available.",
286	    );
287	  }
288	  const evaluations = pick("get_trace_evaluations");
289	  if (evaluations) {
290	    tools[`${TOOL_KEY_PREFIX}get_trace_evaluations`] = ownTraceTool(
291	      evaluations,
292	      userId,
293	      ["evaluation_id", "span_id"],
294	      "Pages through the evaluations of one of the current user's own traces by trace_id (offset/limit and run/response paging). Only trace ids from this user's conversations are allowed; evaluation_id and span_id are not available.",
295	    );
296	  }
297	  return tools;
298	}
299	
300	/** Neatlogs' own totals for one trace, as get_trace_context reports them. */
301	export type TraceMetrics = {
302	  /** False while Neatlogs is still ingesting the trace; the totals are 0 until it is finalized. */
303	  finalized: boolean;
304	  costUsd: number;
305	  tokens: number;
306	  inputTokens: number;
307	  outputTokens: number;
308	};
309	
310	const finite = (value: unknown): number => (typeof value === "number" && Number.isFinite(value) && value >= 0 ? value : 0);
311	
312	/**
313	 * Server-side lookup of one trace's cost and tokens through the shared (project-level) Neatlogs MCP
314	 * client. Never exposed to an agent: callers must pass only a trace id the server itself created
315	 * for the requesting user. Asks for a single span and no evaluations, since only the trace totals
316	 * are read (span payloads are ignored; Neatlogs rejects `fields` projection for now). Resolves to
317	 * null when the trace is not (yet) known to Neatlogs, the key is missing, or the result can't be read.
318	 */
319	export async function getTraceMetrics(traceId: string): Promise<TraceMetrics | null> {
320	  const tool = (await getAllNeatlogsTools())[`${TOOL_KEY_PREFIX}get_trace_context`];
321	  if (!tool?.execute) return null;
322	  let raw: unknown;
323	  try {
324	    raw = await tool.execute(
325	      { trace_id: traceId, include_evaluations: false, limit: 1 } as never,
326	      {} as ExecuteContext,
327	    );
328	  } catch {
329	    return null; // "Trace not found" (not ingested yet) is reported as a thrown tool error.
330	  }
331	  const parsed = parseResult(raw);
332	  if (!isRecord(parsed) || typeof parsed.trace_id !== "string" || parsed.trace_id.toLowerCase() !== traceId.toLowerCase()) {
333	    return null;
334	  }
335	  const inputTokens = finite(parsed.prompt_tokens);
336	  const outputTokens = finite(parsed.completion_tokens);
337	  return {
338	    finalized: parsed.finalization_status === "finalized",
339	    costUsd: finite(parsed.total_cost),
340	    tokens: finite(parsed.total_tokens) || inputTokens + outputTokens,
341	    inputTokens,
342	    outputTokens,
343	  };
344	}
