1	// Per-turn usage row under the chat header pill: the latest turn's cost and tokens against the
2	// user's caps for this agent (our estimate, which the caps use), Neatlogs' own numbers for the
3	// turn's trace once they arrive, and an inline editor for the caps.
4	import { useId, useState } from "react";
5	import { Button } from "@/components/ui/button";
6	import { Input } from "@/components/ui/input";
7	import type { AgentCaps } from "@/hooks/useAgentCaps";
8	import { cn } from "@/lib/utils";
9	import {
10	  formatTokens,
11	  formatUsd,
12	  type NeatlogsUsage,
13	  parseCapsInput,
14	  type TurnUsage,
15	  type UsageLevel,
16	  usageFraction,
17	  usageLevel,
18	} from "@/lib/turn-usage";
19	
20	const BAR_COLOR: Record<UsageLevel, string> = {
21	  normal: "bg-foreground/55",
22	  warn: "bg-warning",
23	  capped: "bg-destructive",
24	};
25	
26	function UsageBar({
27	  label,
28	  used,
29	  cap,
30	  capped,
31	  format,
32	  hint,
33	}: {
34	  label: string;
35	  used: number;
36	  cap: number;
37	  capped: boolean;
38	  format: (value: number) => string;
39	  hint?: string;
40	}) {
41	  const level = usageLevel(used, cap, capped);
42	  const percent = Math.round(usageFraction(used, cap) * 100);
43	  return (
44	    <div className="flex min-w-0 flex-1 flex-col gap-1" title={hint}>
45	      <div className="flex items-baseline justify-between gap-2 text-[12.5px]">
46	        <span className="text-muted-foreground">{label}</span>
47	        <span className={cn("tabular-nums", level === "capped" ? "text-destructive" : "text-foreground/85")}>
48	          {format(used)} / {format(cap)}
49	        </span>
50	      </div>
51	      <div
52	        role="meter"
53	        aria-label={`${label} used this turn`}
54	        aria-valuemin={0}
55	        aria-valuemax={100}
56	        aria-valuenow={percent}
57	        aria-valuetext={`${format(used)} of ${format(cap)}`}
58	        className="h-1 overflow-hidden rounded-full bg-muted"
59	      >
60	        <div
61	          className={cn(
62	            "h-full rounded-full transition-[width,background-color] duration-(--motion-base) ease-(--ease-standard)",
63	            BAR_COLOR[level],
64	          )}
65	          style={{ width: `${percent}%` }}
66	        />
67	      </div>
68	    </div>
69	  );
70	}
71	
72	/**
73	 * Neatlogs' own cost and tokens for the turn's trace, next to our estimate in the bars above:
74	 * "checking Neatlogs…" while the server waits for the trace, then the numbers, or "not available
75	 * yet" when Neatlogs had no finalized trace in time.
76	 */
77	function NeatlogsLine({ usage, neatlogs }: { usage: TurnUsage; neatlogs: NeatlogsUsage }) {
78	  const title = `Neatlogs trace ${neatlogs.traceId}`;
79	  if (neatlogs.status === "pending") {
80	    return (
81	      <div data-testid="neatlogs-usage" data-status="pending" title={title} className="flex items-center gap-1.5 text-[12px] text-muted-foreground">
82	        <span aria-hidden className="h-1.5 w-1.5 rounded-full bg-muted-foreground/60" style={{ animation: "rkPulse 1.2s ease-in-out infinite" }} />
83	        <span>Checking Neatlogs…</span>
84	      </div>
85	    );
86	  }
87	  if (neatlogs.status === "unavailable" || neatlogs.costUsd === undefined || neatlogs.tokens === undefined) {
88	    return (
89	      <div data-testid="neatlogs-usage" data-status="unavailable" title={title} className="text-[12px] text-muted-foreground">
90	        Neatlogs: not available yet
91	      </div>
92	    );
93	  }
94	  return (
95	    <div
96	      data-testid="neatlogs-usage"
97	      data-status="ready"
98	      title={title}
99	      className="flex items-baseline justify-between gap-2 text-[12.5px]"
100	    >
101	      <span className="text-muted-foreground">
102	        Est. {formatUsd(usage.costUsd)} · {formatTokens(usage.tokens)}
103	      </span>
104	      <span className="tabular-nums text-foreground/85">
105	        Neatlogs {formatUsd(neatlogs.costUsd)} · {formatTokens(neatlogs.tokens)} tokens
106	      </span>
107	    </div>
108	  );
109	}
110	
111	export function UsagePanel({
112	  id,
113	  usage,
114	  neatlogs = null,
115	  caps,
116	}: {
117	  id: string;
118	  usage: TurnUsage | null;
119	  /** Neatlogs' own numbers for the latest finished turn; null while it runs or without a trace. */
120	  neatlogs?: NeatlogsUsage | null;
121	  caps: AgentCaps;
122	}) {
123	  const [editing, setEditing] = useState(false);
124	  const current = caps.caps ?? (usage ? { costCapUsd: usage.capCostUsd, tokenCap: usage.capTokens } : caps.defaults);
125	  const usedCost = usage?.costUsd ?? 0;
126	  const usedTokens = usage?.tokens ?? 0;
127	  return (
128	    <section
129	      id={id}
130	      aria-label="Usage this turn"
131	      className="pointer-events-auto mt-2 flex w-[min(380px,calc(100vw-2rem))] flex-col gap-2.5 rounded-2xl border border-border bg-card/95 px-3.5 py-3 shadow-sm backdrop-blur"
132	    >
133	      <div className="flex items-end gap-4">
134	        <UsageBar label="Cost" used={usedCost} cap={current.costCapUsd} capped={usage?.reason === "cost"} format={formatUsd} />
135	        <UsageBar
136	          label="Tokens"
137	          used={usedTokens}
138	          cap={current.tokenCap}
139	          capped={usage?.reason === "tokens"}
140	          format={formatTokens}
141	          hint={usage?.cachedInputTokens ? `${formatTokens(usage.cachedInputTokens)} cached` : undefined}
142	        />
143	      </div>
144	      {usage && neatlogs ? <NeatlogsLine usage={usage} neatlogs={neatlogs} /> : null}
145	      {editing ? (
146	        <CapsEditor caps={caps} current={current} onDone={() => setEditing(false)} />
147	      ) : (
148	        <div className="flex items-center justify-between gap-2 text-[12px] text-muted-foreground">
149	          <span>Latest turn (estimated), per-message limits for this bot.</span>
150	          <Button size="xs" variant="ghost" onClick={() => setEditing(true)}>
151	            Edit
152	          </Button>
153	        </div>
154	      )}
155	    </section>
156	  );
157	}
