159	function CapsEditor({
160	  caps,
161	  current,
162	  onDone,
163	}: {
164	  caps: AgentCaps;
165	  current: { costCapUsd: number; tokenCap: number };
166	  onDone: () => void;
167	}) {
168	  const ids = useId();
169	  const [cost, setCost] = useState(String(current.costCapUsd));
170	  const [tokens, setTokens] = useState(String(current.tokenCap));
171	  const [errors, setErrors] = useState<{ cost?: string; tokens?: string; form?: string }>({});
172	  const [busy, setBusy] = useState(false);
173	
174	  const run = async (action: () => Promise<string | null>) => {
175	    setBusy(true);
176	    const error = await action();
177	    setBusy(false);
178	    if (error) setErrors({ form: error });
179	    else onDone();
