import { useCallback, useEffect, useSyncExternalStore } from "react";
import { handleUnauthorized } from "@/lib/auth";

export type CfoStatus = { configured: boolean; connected: boolean; expiresAt?: number | string };

/** Shared by every consumer (account menu, chat banner), so one refetch updates them all. */
let current: CfoStatus | null = null;
const listeners = new Set<() => void>();

function publish(next: CfoStatus | null) {
  current = next;
  for (const listener of listeners) listener();
}

/** GET /api/cfo/status; leaves the last known value on failure. */
export async function refetchCfoStatus(): Promise<void> {
  try {
    const res = await fetch("/api/cfo/status", { credentials: "include" });
    if (res.status === 401) return handleUnauthorized();
    if (res.ok) publish((await res.json()) as CfoStatus);
  } catch {
    // Offline or server down: the connect UI simply stays hidden.
  }
}

/** POST /api/cfo/disconnect, then refresh. Returns whether the server accepted it. */
export async function disconnectCfo(): Promise<boolean> {
  try {
    const res = await fetch("/api/cfo/disconnect", { method: "POST", credentials: "include" });
    if (res.status === 401) {
      handleUnauthorized();
      return false;
    }
    await refetchCfoStatus();
    return res.ok;
  } catch {
    return false;
  }
}

/** Full-page navigation: the server redirects to cfo.ai and back to `/?cfo=connected|error`. */
export function startCfoConnect() {
  window.location.assign("/api/cfo/connect");
}

const subscribe = (listener: () => void) => {
  listeners.add(listener);
  return () => void listeners.delete(listener);
};

/** The signed-in user's cfo.ai link state; `status` is null until the first answer. */
export function useCfoStatus() {
  const status = useSyncExternalStore(subscribe, () => current);
  useEffect(() => {
    if (!current) void refetchCfoStatus();
  }, []);
  const refetch = useCallback(() => refetchCfoStatus(), []);
  return { status, refetch };
}
48:## Usage caps
49-
50-Every chat turn (one user message, or one approval resume, and everything the agent does to answer it: all model steps, tool calls and delegated sub-agent calls) is limited per user and per agent by a **cost cap** (default $0.25) and a **token cap** (default 300,000 tokens). Each user sets their own caps per agent; they are stored in `data/auth.db` (`agent_caps`) and persist across sessions and restarts. The caps of the agent being chatted with apply, including to the sub-agents it delegates to.
51-
52-- `GET /api/agents/:agentId/caps` returns `{ costCapUsd, tokenCap, defaults }`; `PUT` with `{ costCapUsd, tokenCap }` saves them (both must be greater than 0; at most 1000 USD and 100,000,000 tokens); `DELETE` resets to the defaults. Signed-in users only, own caps only.
53-- Cost is estimated from `src/usage/pricing.ts` (DeepSeek's published peak prices; input tokens the provider reports as cache hits, `usage.cachedInputTokens`, are priced at the cache-hit rate and the rest at the cache-miss rate, and a step that reports no cached count is priced entirely at the cache-miss rate; unknown models use a high fallback price).
54-- A processor on every agent (`src/usage/turn-budget.ts`) adds up each model step's usage. Once a cap is exceeded the run stops before the next model call (tools the last step requested still run); the partial reply is kept and a closing note explains which limit was hit.

